(async()=>{
if (location.protocol !== "file:") {
const params=new URLSearchParams(location.search);
let scenario=params.get('mode')==='case_scenarios',reviewer=params.get('mode')==='reviewer';const checked=new Set();
if(!params.has('set')&&!params.has('attempt'))location.replace('/sets.html');
let collectionError='';let collectionIDs=null;try{if(params.get('collection'))collectionIDs=new Set(Collections.read().find(c=>c.id===params.get('collection'))?.questions||[])}catch(e){collectionError=e.message;collectionIDs=new Set()}
let qs=window.QUESTIONS.filter(q=>(!scenario||q.case_id)&&(!params.has('cases')||params.get('cases').split(',').includes(q.case_id))&&(!params.get('case')||q.case_id===params.get('case'))&&(!collectionIDs||collectionIDs.has(q.id))&&(!params.get('subject')||q.subject===params.get('subject'))&&(!params.get('topic')||q.topic===params.get('topic')));
if(!qs.length&&!params.has('attempt')){document.querySelector('main').innerHTML='<section><h1>No questions in this set</h1><p>This selection has no saved questions. Choose another collection or clear the subject and topic filters.</p><a href="/sets.html">Choose a set</a></section>';}else {
let attemptID=params.get("attempt")||crypto.randomUUID();let savedResult=null,started;
try{started=params.has('attempt')?await Account.request('/api/attempt?id='+encodeURIComponent(attemptID)):await Account.request('/api/attempts/start',{id:attemptID,mode:scenario?'case_scenarios':reviewer?'reviewer':'exam',question_ids:qs.map(q=>q.id)});if(started.result){location.replace('/history.html');return;}qs=started.questions;reviewer=started.mode==='reviewer';scenario=started.mode==='case_scenarios';history.replaceState(null,'','/?set=1&attempt='+encodeURIComponent(attemptID));}catch(e){document.querySelector('.workspace').textContent='Could not start a saved attempt. '+e.message+' Reload to try again.';return;}
document.querySelector('aside h1').textContent=started.ranked_exam_id?qs[0]?.subject||'Ranked exam':params.get('subject')||'All subjects';
document.querySelector('aside .subtle').textContent=started.ranked_exam_id?'Ranked exam · '+(qs[0]?.topic||''):params.get('topic')||'All topics';
if(params.get('collection'))document.querySelector('aside h1').textContent=Collections.read().find(c=>c.id===params.get('collection'))?.name||'Collection';
const confirmed=new Set(started.draft?.confirmed||[]);let confirming=false;
const reviewedCases=new Set(started.draft?.reviewed_cases||[]);
const answers=started.draft?.answers||qs.map(q=>q.type==='range'?'':[]);let current=started.draft?.current||0,submitted=false;let draftRevision=started.draft_revision||0,saveChain=Promise.resolve(),unsaved=false,saveVersion=0;let startTime=started.started;const sessionBar=document.createElement('div');sessionBar.innerHTML='<p id="exam-timer"></p><p id="save-progress" role="status">Progress saved. Resume from My attempts.</p><a href="/history.html">My attempts / resume later</a>';document.querySelector('.workspace').prepend(sessionBar);function tick(){document.getElementById('exam-timer').textContent=reviewer?'':('Elapsed time: '+AttemptUI.duration(Math.max(0,Date.now()-Date.parse(startTime))));}const clock=setInterval(()=>{if(!submitted)tick()},1000);tick();function persist(confirmQuestion=null){unsaved=true;const version=++saveVersion;const snapshot=JSON.parse(JSON.stringify(answers)),position=current,reviewed=[...reviewedCases];document.getElementById('save-progress').textContent='Saving progress…';saveChain=saveChain.catch(()=>{}).then(async()=>{const result=await Account.request('/api/attempts/progress',{id:attemptID,answers:snapshot,current:position,reviewed_cases:reviewed,revision:draftRevision,confirm_question:confirmQuestion});draftRevision=result.revision;for(const id of result.confirmed||[])confirmed.add(id);if(result.findings)for(const q of qs)q.additional_findings=result.findings[q.id]||'';if(version===saveVersion){unsaved=false;document.getElementById('save-progress').textContent='Progress saved. Resume from My attempts.';}}).catch(e=>{unsaved=true;document.getElementById('save-progress').textContent='Progress not saved: '+e.message;throw e});saveChain.catch(()=>{});}
const $=id=>document.getElementById(id);const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(qs.some(q=>q.staged_case)){const note=document.querySelector('.session-note');for(const node of note.childNodes)if(node.nodeType===Node.TEXT_NODE)node.textContent=' Confirmed case answers are locked. Other answers can be changed before submitting.';}
if(scenario){document.title='DrillSpace · Case scenarios';document.querySelector('.footer').before($('feedback'));document.querySelector('.local-note').textContent='Submit each answer for feedback, then Continue. Progress saves automatically. Resume from My attempts; elapsed time includes time away.';}
$("bank-size").textContent=`${qs.length} questions · ${qs.reduce((n,q)=>n+q.maximum,0)} points`;
window.addEventListener('beforeunload',e=>{if(!submitted&&unsaved){e.preventDefault();e.returnValue=''}});
const shared=document.createElement('section');shared.id='shared-case';shared.className='shared-case';$('question').before(shared);
function reveal(q){return submitted||(scenario&&confirmed.has(q.id))||(reviewer&&(checked.has(current)||confirmed.has(q.id)||(q.type==='single'&&answered(current))))}
function invalidate(q){document.querySelectorAll('.choice-score-badge,.choice-selected-label').forEach(el=>el.remove());checked.delete(current);if(q.case_id){reviewedCases.delete(q.case_id);window.renderDiscussion?.(q,false)}}
function answered(i){return answers[i].length>0}
function grade(q,a){if(a.length===0)return q.blank;let raw;if(q.type==='range'){const n=Number(a);raw=n>=q.lower&&n<=q.upper?q.correct:q.incorrect;}else if(['per_choice','sum_choices'].includes(q.method))raw=a.reduce((sum,v)=>sum+q.choice_scores[v],0);else if(q.method==='exact_match')raw=a.length===q.accepted.length&&a.every(v=>q.accepted.includes(v))?q.correct:q.incorrect;else raw=a.reduce((sum,v)=>sum+(q.accepted.includes(v)?q.correct:q.incorrect),0);return Math.round(Math.min(q.maximum,Math.max(q.minimum,raw))*100)/100;}
function navResult(q,i){
 if(!answered(i))return {kind:'blank',label:'Unanswered'};
 const visible=submitted||(scenario&&confirmed.has(q.id))||(reviewer&&(checked.has(i)||confirmed.has(q.id)||q.type==='single'));
 if(!visible)return {kind:'pending',label:'Answered · not graded yet'};
 const score=submitted?savedResult.items[i].score:grade(q,answers[i]);
 return score>=q.maximum?{kind:'correct',label:'Correct'}:score>0?{kind:'partial',label:'Partial credit'}:{kind:'wrong',label:'Wrong'};
}
function updateNav(){const n=answers.filter((_,i)=>answered(i)).length;$('progress').max=qs.length;$('progress').value=n;$('progress-label').textContent=`${n} of ${qs.length} answered`;$('progress-percent').textContent=`${Math.round(n/qs.length*100)}%`;$('navigator').innerHTML=qs.map((q,i)=>{const result=navResult(q,i);return `<button class="qnav ${i===current?'current':''} nav-${result.kind}" aria-label="Question ${q.display_label||i+1}, ${result.label}" title="${result.label}" ${i===current?'aria-current="step"':''} ${stageOpen(i)?'':'disabled'} data-index="${i}">${q.display_label||i+1}</button>`}).join('');document.querySelectorAll('.qnav').forEach(b=>b.onclick=()=>navigate(Number(b.dataset.index)));const legend=document.querySelector('aside .legend');if(legend)legend.innerHTML='<span><i></i> Unanswered</span><span><i class="nav-correct"></i> Correct</span><span><i class="nav-wrong"></i> Wrong</span><span><i class="nav-partial"></i> Partial credit</span>'+(!submitted?'<span><i class="nav-pending"></i> Answered · not graded</span>':'');}

function validateCurrent(){const q=qs[current];if(q.type==='range'&&answers[current]!==''&&(!Number.isFinite(Number(answers[current]))||(!q.decimals&&!Number.isInteger(Number(answers[current]))))){$('error').textContent=q.decimals?'Please enter a valid number.':'Please enter a whole number.';return false;}$('error').textContent='';return true;}
function stageOpen(i){const q=qs[i];return submitted||!q.staged_case||qs.slice(0,i).filter(x=>x.case_id===q.case_id).every(x=>confirmed.has(x.id))}
function navigate(i){if(confirming||!stageOpen(i)){ $('error').textContent='Confirm the current stage before opening the next question in this case.';return;}if(!validateCurrent())return;current=i;if(!submitted)persist();render();$('question').focus();}
function render(){const q=qs[current],locked=submitted||confirming||confirmed.has(q.id);updateNav();
 shared.hidden=!q.case;
 if(q.case){shared.dataset.caseId=q.case_id;shared.innerHTML=`<h2>Case ${esc(q.case_id)} — ${esc(q.case.title)}</h2>`+[['History',q.case.history],['Physical examination',q.case.examination],['Laboratory findings',q.case.laboratory]].filter(([t,v])=>v).map(([t,v])=>`<section class="case-section"><h3>${t}</h3><div class="formatted-text">${RichText.render(v)}</div></section>`).join('');}
if(q.case){for(const x of qs.slice(0,current+1).filter(x=>x.case_id===q.case_id&&x.additional_findings)){const section=document.createElement('section');section.innerHTML=`<h3>Additional findings — ${esc(x.display_label)}</h3><div class="formatted-text">${RichText.render(x.additional_findings)}</div>`;shared.append(section)}}
$('question').tabIndex=-1;const type=q.type==='multi'?'Select all that apply':q.type==='range'?'Numerical answer':'Select one answer';const rule=['per_choice','sum_choices'].includes(q.method)?`${q.method==='per_choice'?'Each choice has its own score':'Selected option scores are added'} · maximum ${q.maximum} · minimum ${q.minimum}`:q.method==='partial_credit'?`+${q.correct} per correct selection · ${q.incorrect} per incorrect selection · minimum ${q.minimum}`:`${q.maximum} point${q.maximum===1?'':'s'} for a correct answer · ${q.incorrect} for an incorrect answer`;
 const modeLabel=document.querySelector('header .divider + span');if(modeLabel)modeLabel.textContent=scenario?'Case scenarios':reviewer?'Reviewer mode':'Exam mode';
 $('question').innerHTML=`<div class="meta"><span>QUESTION ${q.display_label||current+1} OF ${qs.length} &nbsp; / &nbsp; ${esc(q.display_code||q.id)}</span><span class="badge">${q.maximum} point${q.maximum===1?'':'s'}</span></div>${window.presentQuestion(q.text)}<p class="rule">${type}<br>${rule}</p>${q.image?`<button class="image-button" id="show-image" aria-label="Enlarge ECG for ${esc(q.id)}"><img src="${esc(q.image)}" alt="ECG supplied for question ${esc(q.id)}"><span>Click to enlarge</span></button>`:''}${q.type==='range'?`<label class="numeric-label" for="numeric">Your answer${q.decimals?' (decimals allowed)':''}</label><input id="numeric" class="numeric" type="text" inputmode="decimal" autocomplete="off" value="${esc(answers[current])}" ${locked?'disabled':''}>`:`<fieldset style="border:0;padding:0;margin:0"><legend class="eyebrow" style="margin-bottom:12px">YOUR ANSWER</legend><div class="options">${q.choices.map(c=>`<label class="option"><input type="${q.type==='multi'?'checkbox':'radio'}" name="answer" value="${esc(c.id)}" ${answers[current].includes(c.id)?'checked':''} ${locked?'disabled':''}><span class="letter">${esc(c.id)}</span><span>${RichText.inline(c.text)}</span></label>`).join('')}</div></fieldset>`}${locked?'':'<button class="clear" id="clear">Clear answer</button>'}`;
 if(submitted){
 const item=savedResult.items[current];
 const status=item.blank?'unanswered':item.score>=item.maximum?'correct':item.score>0?'partial':'incorrect';
 const statusText=item.blank?'Unanswered':item.score>=item.maximum?'Full credit':item.score>0?'Partial credit':'No credit / deduction';
 const statusLabel=document.createElement('p');statusLabel.className='answer-status result-'+status;statusLabel.textContent=statusText;$('question').append(statusLabel);
 if(q.type==='range'){$('numeric').classList.add('result-'+status);}
 else if(!q.choice_scores)document.querySelectorAll('.option').forEach(option=>{
 const input=option.querySelector('input');const accepted=q.accepted.includes(input.value);
 const partial=q.method==='per_choice'&&q.choice_scores[input.value]>0&&q.choice_scores[input.value]<q.maximum;if(accepted||input.checked){option.classList.add(partial?'result-partial':accepted?'result-correct':'result-incorrect');const label=document.createElement('strong');label.className='choice-result';label.textContent=partial?'Partial credit · Your answer':accepted?(input.checked?'Correct · Your answer':'Correct answer'):'Incorrect · Your answer';option.append(label);}
 });
 }
 Collections.render(q);
 if(q.image)$('show-image').onclick=()=>{$('large-picture').src=q.image;$('picture').showModal()};
 if(!locked){if(q.type==='range')$('numeric').oninput=e=>{answers[current]=e.target.value.trim();invalidate(q);$('feedback').hidden=true;persist();updateNav()};else document.querySelectorAll('input[name="answer"]').forEach(el=>el.onchange=()=>{invalidate(q);$('feedback').hidden=true;answers[current]=[...document.querySelectorAll('input[name="answer"]:checked')].map(e=>e.value);persist();updateNav();if(reviewer&&q.type==='single'){checked.add(current);render()}});$('clear').onclick=()=>{answers[current]=q.type==='range'?'':[];invalidate(q);persist();render()};}
 if(reviewer&&!submitted&&q.type!=='single'){const b=document.createElement('button');b.className='primary';b.textContent='Check answer';b.onclick=()=>{if(validateCurrent()&&answered(current)){checked.add(current);render()}};$('question').append(b);}

 if(q.staged_case&&!submitted){
 const note=document.createElement('p');note.textContent=locked?'Answer submitted and locked.':scenario?'Submit your answer to see feedback. You can then continue to the next question.':'Confirming locks this answer and reveals the next stage. You cannot change it afterward.';$('question').append(note);
 if(!locked){const b=document.createElement('button');b.className='primary';b.textContent=scenario?'Submit answer':'Confirm and continue';b.disabled=confirming;b.onclick=async()=>{if(!validateCurrent()||!answered(current)){$('error').textContent='Answer this question before confirming.';return;}confirming=true;document.querySelectorAll('#question input,#question button').forEach(el=>el.disabled=true);try{persist(q.id);await saveChain;const next=qs.findIndex((x,i)=>i>current&&x.case_id===q.case_id);if(next>=0&&!scenario)current=next;persist();await saveChain;render();}catch(e){$('error').textContent=e.message;}finally{confirming=false;render();}};$('question').append(b);}
 }
 if(reveal(q)&&q.choice_scores&&q.type!=='range'){
 document.querySelectorAll('.option').forEach(option=>{
 const input=option.querySelector('input'),score=q.choice_scores[input.value];if(!Number.isFinite(score))return;
 const kind=score<0?'penalty':score===0?'zero':score>=q.maximum?'full':'partial';
 const label={full:'Full credit',partial:'Partial credit',zero:'No credit',penalty:'Penalty'}[kind];
 const badge=document.createElement('strong');badge.className='choice-score-badge score-'+kind;badge.textContent=String(score).replace('-','−')+' · '+label;option.append(badge);
 if(input.checked){const chosen=document.createElement('small');chosen.className='choice-selected-label';chosen.textContent='Your answer';option.querySelector('.letter').after(chosen);}
 });
 }
 $('feedback').hidden=!reveal(q);if(reveal(q)){const value=submitted?savedResult.items[current].score:grade(q,answers[current]);const accepted=q.type==='range'?`${q.lower}–${q.upper}, inclusive${q.decimals?' (decimals accepted)':''}`:q.choices.filter(c=>q.accepted.includes(c.id)).map(c=>`${c.id}. ${c.text}`).join('; ');$('feedback').innerHTML=`<h3>${value} / ${q.maximum} points${!answered(current)?' · Unanswered':''}</h3><p><strong>Full-credit answer:</strong> ${RichText.inline(accepted)}</p>${q.explanation?`<div class="formatted-text">${RichText.render(q.explanation)}</div>`:"<p>Marked using the saved answer key.</p>"}${RichText.explanationImage(q)}`;}
 window.renderDiscussion?.(q,q.case_id?reveal(q):reviewer||submitted);
 window.EditorTools?.show(q);
 $('back').disabled=current===0;$('next').disabled=scenario&&!submitted&&!confirmed.has(q.id);$('finish').disabled=scenario&&!submitted&&qs.some(x=>!confirmed.has(x.id));$('next').textContent=current===qs.length-1?(submitted?'Back to first':scenario?'Finish scenarios':reviewer?'Finish review':'Submit exam'):scenario?'Continue':'Next question';$('position').textContent=`${current+1} / ${qs.length}`;$('finish').hidden=submitted;$('finish').textContent=scenario?'Finish scenarios':reviewer?'Finish review':'Submit exam';
}
function finish(){if(confirming||!validateCurrent())return;if(scenario&&qs.some(q=>!confirmed.has(q.id))){$('error').textContent='Submit each answer before finishing this case.';return;}$('submit').textContent=scenario?'Save case result':reviewer?'Save review result':'Submit exam';const blank=answers.filter((_,i)=>!answered(i)).length;$('confirm-text').textContent=blank?`${blank} question${blank===1?' is':'s are'} unanswered. Their saved unanswered-scoring rules will apply. Submit to save your result and review the answers.`:'All questions are answered. Submit to see your score and review the accepted answers.';$('confirm').showModal();}
async function submit(){if(!validateCurrent())return;$('submit').disabled=true;try{persist();await saveChain;savedResult=await Account.request('/api/attempts/submit',{id:attemptID,answers,revision:draftRevision});}catch(e){$('error').textContent='Your result was not saved. '+e.message;$('confirm-text').textContent='Submission could not be saved. '+e.message+' Try submitting again.';return;}finally{$('submit').disabled=false;}submitted=true;try{qs=(await Account.request('/api/attempt?id='+encodeURIComponent(attemptID))).questions}catch(e){$('error').textContent='Result saved. Open My attempts to view all case findings.';}document.getElementById('save-progress').textContent='Result saved.';$('confirm').close();const total=savedResult.total,max=savedResult.maximum;$('results').hidden=false;$('results').innerHTML=`<div class="summary"><div><p>YOUR RESULT</p><strong>${total} <span style="font-size:20px;font-weight:normal">/ ${max}</span></strong><p>Saved to your attempt history. Review each question below.</p>${scenario?`<p>Case scenarios · Elapsed: ${AttemptUI.duration(Date.now()-Date.parse(startTime))}</p>`:''}${AttemptUI.legend()}</div><button class="secondary" id="restart">Try again</button></div>`;if(scenario)$('results').insertAdjacentHTML('beforeend',AttemptUI.scenarioSummary(qs,savedResult));$('restart').onclick=async()=>{const button=$('restart');button.disabled=true;try{if(started.ranked_exam_id){const ranked=await Account.request('/api/ranked-exams/start',{exam_id:started.ranked_exam_id});location.href='/?set=1&attempt='+encodeURIComponent(ranked.id);return;}const nextID=crypto.randomUUID();const started=await Account.request('/api/attempts/start',{id:nextID,mode:scenario?'case_scenarios':reviewer?'reviewer':'exam',question_ids:qs.map(q=>q.id)});attemptID=nextID;qs=started.questions;startTime=started.started;draftRevision=0;unsaved=false;saveChain=Promise.resolve();history.replaceState(null,'','/?set=1&attempt='+encodeURIComponent(attemptID));}catch(e){$('error').textContent=e.message;button.disabled=false;return;}answers.splice(0,answers.length,...qs.map(q=>q.type==='range'?'':[]));submitted=false;checked.clear();reviewedCases.clear();confirmed.clear();shared.dataset.caseId="";current=0;$('results').hidden=true;render()};current=0;render();window.scrollTo({top:0,behavior:'smooth'});}
 $('back').onclick=()=>navigate(current-1);$('next').onclick=()=>{if(current<qs.length-1)navigate(current+1);else if(submitted)navigate(0);else finish()};$('finish').onclick=finish;$('cancel').onclick=()=>$('confirm').close();$('submit').onclick=submit;$('close-picture').onclick=()=>$('picture').close();render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_quiz_question',description:'Navigate to a quiz question without changing or submitting answers.',inputSchema:{type:'object',properties:{question_number:{type:'integer',minimum:1,maximum:qs.length}},required:['question_number'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.question_number)||input.question_number<1||input.question_number>qs.length)throw Error('Invalid question number');navigate(input.question_number-1);return {question_number:current+1,question_id:qs[current].id};}})).catch(()=>{});}catch{}}

}
}

})();
